import{t as e}from"./utils-COoNfFoj.js";var t={slug:`oren-john`,influencerName:`Oren John`,influencerHandle:`@orenmeetsworld`,influencerAvatarUrl:`${e}/oren-john-avatar.png`,heroDescription:`I created this build because I have all this health data that I track and pay for, but no way to get a holistic view of everything or to ask questions in a place with full context of all the data I have.`,assetTitle:`Personal Health Dashboard Web App`,screenshotUrl:`${e}/oren-john.png`,remixUrl:`https://www.perplexity.ai/computer/a/health-os-oren-john-1thlUZZ_SmCSIesKgvh4Rg`,promptTitle:`Try Oren's prompt`,promptText:`Build a personal health dashboard web app in a warm, editorial brand style. Pull all metrics from connected Perplexity Health data sources — if nothing is connected, show a prompt guiding the user to connect their devices. Include four goal-tracking categories (Fitness & Performance, Body Composition, Longevity & Biomarkers, Habits & Lifestyle), each with 5 goals as animated progress bars showing current vs. target values and a status badge (On Track / Watch / Achieved) calibrated to the year's elapsed progress. Use a cream and terracotta palette, serif + sans-serif typography, and deploy as a fully responsive single-page app.`};export{t as default};
